(()=>{window.AK_SLIDES=[{img:"step-1-api-settings.png",text:'\u0412 \u043A\u0430\u0431\u0438\u043D\u0435\u0442\u0435 \u043F\u0440\u043E\u0434\u0430\u0432\u0446\u0430 Wildberries \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u043D\u0430 \u043F\u0440\u043E\u0444\u0438\u043B\u044C \u0441\u043F\u0440\u0430\u0432\u0430 \u0432\u0432\u0435\u0440\u0445\u0443 \u0438 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 <b>\xAB\u0418\u043D\u0442\u0435\u0433\u0440\u0430\u0446\u0438\u0438 \u043F\u043E API\xBB</b>. \u0421\u0441\u044B\u043B\u043A\u0430 \u0441\u0440\u0430\u0437\u0443: <a href="https://seller.wildberries.ru/supplier-settings/access-to-api" target="_blank" rel="noopener">\u0414\u043E\u0441\u0442\u0443\u043F \u043A API</a>. \u0415\u0441\u043B\u0438 \u0443 \u0432\u0430\u0441 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043A\u043E\u043C\u043F\u0430\u043D\u0438\u0439 (\u0418\u041F, \u041E\u041E\u041E), \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0442\u0443, \u0447\u0435\u0439 \u043C\u0430\u0433\u0430\u0437\u0438\u043D \u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0430\u0435\u0442\u0435.'},{img:"step-2-create-token.png",text:"\u041D\u0430\u0436\u043C\u0438\u0442\u0435 <b>\xAB\u0421\u043E\u0437\u0434\u0430\u0442\u044C \u0442\u043E\u043A\u0435\u043D\xBB</b>. \u0415\u0441\u043B\u0438 \u0442\u0430\u043C \u043D\u0430\u043F\u0438\u0441\u0430\u043D\u043E \xAB20 \u0438\u0437 20\xBB, \u0443\u0434\u0430\u043B\u0438\u0442\u0435 \u043D\u0435\u043D\u0443\u0436\u043D\u044B\u0439 \u0441\u0442\u0430\u0440\u044B\u0439 \u0442\u043E\u043A\u0435\u043D."},{img:"step-3-token-type.png",text:"\u0412\u043A\u043B\u0430\u0434\u043A\u0430 \xAB\u0414\u043B\u044F \u0438\u043D\u0442\u0435\u0433\u0440\u0430\u0446\u0438\u0438 \u0432\u0440\u0443\u0447\u043D\u0443\u044E\xBB. \u0422\u0438\u043F \u0442\u043E\u043A\u0435\u043D\u0430 \u2014 \u0441\u0442\u0440\u043E\u0433\u043E <b>\xAB\u041F\u0435\u0440\u0441\u043E\u043D\u0430\u043B\u044C\u043D\u044B\u0439\xBB</b>. \u041D\u0430\u0437\u0432\u0430\u043D\u0438\u0435 \u043B\u044E\u0431\u043E\u0435, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \xABNR-Space\xBB. \u041E\u0442\u043C\u0435\u0442\u044C\u0442\u0435 <b>\u0432\u0441\u0435 \u043A\u0430\u0442\u0435\u0433\u043E\u0440\u0438\u0438</b>: \u041A\u043E\u043D\u0442\u0435\u043D\u0442, \u041C\u0430\u0440\u043A\u0435\u0442\u043F\u043B\u0435\u0439\u0441, \u0421\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043A\u0430, \u0424\u0438\u043D\u0430\u043D\u0441\u044B, \u0410\u043D\u0430\u043B\u0438\u0442\u0438\u043A\u0430, \u041F\u0440\u043E\u0434\u0432\u0438\u0436\u0435\u043D\u0438\u0435, \xAB\u0412\u043E\u043F\u0440\u043E\u0441\u044B \u0438 \u043E\u0442\u0437\u044B\u0432\u044B\xBB, \u0426\u0435\u043D\u044B \u0438 \u0441\u043A\u0438\u0434\u043A\u0438. \u0411\u0435\u0437 \xAB\u0424\u0438\u043D\u0430\u043D\u0441\u043E\u0432\xBB \u043D\u0435 \u043F\u043E\u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u043F\u0440\u0438\u0431\u044B\u043B\u044C, \u0431\u0435\u0437 \xAB\u0412\u043E\u043F\u0440\u043E\u0441\u043E\u0432 \u0438 \u043E\u0442\u0437\u044B\u0432\u043E\u0432\xBB \u043D\u0435 \u0437\u0430\u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u0410\u043A\u044B\u043B\u0430\u0439. \u041F\u043E\u0441\u0442\u0430\u0432\u044C\u0442\u0435 \u0433\u0430\u043B\u043E\u0447\u043A\u0443 \xAB\u042F \u043F\u043E\u043D\u0438\u043C\u0430\u044E\u2026\xBB."},{img:"step-4-access.png",text:"\u0423\u0440\u043E\u0432\u0435\u043D\u044C \u0434\u043E\u0441\u0442\u0443\u043F\u0430 \u2014 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E <b>\xAB\u0427\u0442\u0435\u043D\u0438\u0435 \u0438 \u0437\u0430\u043F\u0438\u0441\u044C\xBB</b>. \xAB\u0422\u043E\u043B\u044C\u043A\u043E \u0447\u0442\u0435\u043D\u0438\u0435\xBB \u043D\u0435 \u043F\u043E\u0434\u043E\u0439\u0434\u0451\u0442: \u0441 \u043D\u0438\u043C \u043D\u0435 \u0440\u0430\u0431\u043E\u0442\u0430\u044E\u0442 \u0410/\u0411-\u0442\u0435\u0441\u0442\u044B, \u0430\u0432\u0442\u043E\u0431\u0438\u0434\u0434\u0435\u0440 \u0438 \u043E\u0442\u0432\u0435\u0442\u044B \u043D\u0430 \u043E\u0442\u0437\u044B\u0432\u044B. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 \xAB\u0421\u043E\u0437\u0434\u0430\u0442\u044C \u0442\u043E\u043A\u0435\u043D\xBB \u0438 \u0441\u043A\u043E\u043F\u0438\u0440\u0443\u0439\u0442\u0435 \u0435\u0433\u043E \u0446\u0435\u043B\u0438\u043A\u043E\u043C."},{input:!0,text:"\u0412\u0441\u0442\u0430\u0432\u044C\u0442\u0435 \u0442\u043E\u043A\u0435\u043D \u0441\u044E\u0434\u0430 \u2014 \u044F \u043F\u0440\u043E\u0432\u0435\u0440\u044E \u0435\u0433\u043E \u0441\u0430\u043C\u0430, \u043D\u0430\u0436\u0438\u043C\u0430\u0442\u044C \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043D\u0443\u0436\u043D\u043E."}];})();
